INSERT INTO s503c_cards VALUES
(3166,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','matthew',10,5,$n$*Go ... rather to the lost sheep of the house of Yashar'el (Israel)* — `lost-sheep-mission-scope`.$n$,$n$Matthew 10:5 — *These twelve Yahusha (Jesus) sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) All power is given to the same Yahusha (Jesus) who first put a fence on the twelve. Before the cross he told them not to go *into the way of the Gentiles*. The sheep he sends them after now are the sheep he named then. The fence comes down only because the sheep are out past it.$n$,8,$n$*Go ... rather to the lost sheep of the house of Yashar'el (Israel)* — `lost-sheep-mission-scope`.$n$,$n$Matthew 10:5 — *Go not into the way of the Gentiles.* The fence on the twelve names who they were sent to, and the sheep behind it are the same sheep the risen one sends them after.$n$),
(3168,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','matthew',4,14,$n$Galilee-of-the-goyim per Yeshayahu 9:1-2 — the territories-of-the-scattered-seed.$n$,$n$Matthew 4:14 — *That it might be fulfilled which was spoken by Isaiah the prophet, saying,* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Before he ever says that power is given, Yahusha (Jesus) is already walking ground Isaiah spoke of, the country of the northern tribes by the sea. Matthew points back to the prophet's word and sets the first light there. The land the commission later spreads over was marked out in the old writings long before.$n$,8,$n$Galilee-of-the-goyim per Yeshayahu 9:1-2 — the territories-of-the-scattered-seed.$n$,$n$Matthew 4:14 — *That it might be fulfilled which was spoken by Isaiah the prophet.* Matthew sends us back to Isaiah's own words for the land of the northern tribes, where the light first came.$n$),
(3169,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','isaiah',11,11,$n$The substantial-recovery-of-the-remnant from-the-four-corners.$n$,$n$Isaiah 11:11 — *And it shall come to pass in that day, that Yahuah (Lord) shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Isaiah says where the hand of Yahuah (Lord) reaches. He sets it out *the second time* to recover the remnant of his people from Assyria, Egypt, Cush, Elam and the islands of the sea. Those are the places the risen one sends the eleven into. The nations in that list are where the people were left, not who the people are.$n$,8,$n$*Yahuah shall set his hand again the second time to recover the remnant of his people ... from the four corners of the earth.*$n$,$n$Isaiah 11:11 — *shall set his hand again the second time to recover the remnant of his people.* The recovery of the remnant from Assyria, Egypt, Cush and the islands names the territories the sending goes out to.$n$),
(3170,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','ezekiel',37,15,$n$The two-sticks-united substance.$n$,$n$Ezekiel 37:15 — *The word of Yahuah (LORD) came again unto me, saying,* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) The word that comes to Ezekiel opens the two sticks. Yahudah (Judah) is written on one, Joseph and Ephraim on the other, and in his hand they become one stick. Power given to the risen one is power to do that joining. The sending after it goes toward the scattered house, the other stick, and not toward some new people.$n$,8,$n$The substantial-substance-of-the-two-sticks-united-substance.$n$,$n$Ezekiel 37:15 — *The word of Yahuah (LORD) came again unto me.* The word to Ezekiel opens the two sticks being made one, which is the work the sending after the rising carries on.$n$),
(3171,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','jeremiah',31,31,$n$The new-covenant heart-Torah substance.$n$,$n$Jeremiah 31:31 — *Behold, the days come, saith Yahuah (LORD), that I will make a new covenant with the house of Yashar'el (Israel), and with the house of Yahudah (Judah):* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) The new covenant is made with the house of Yashar'el (Israel) and the house of Yahudah (Judah), and what it puts in them is the law itself, written on the heart. So when the risen one tells the eleven to teach them to observe all he commanded, the covenant he teaches is Torah kept, not Torah laid down. The houses named here are the houses the sheep belong to.$n$,8,$n$The new-covenant Tanakh-anchor.$n$,$n$Jeremiah 31:31 — *I will make a new covenant with the house of Yashar'el (Israel).* The new covenant is made with the house of Yashar'el (Israel) and the house of Yahudah (Judah), the houses the sent ones are sent to.$n$),
(3173,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','romans',9,25,$n$The Pauline-citation of Hosheia 1:10.$n$,$n$Romans 9:25 — *As he saith also in Hosea, I will call them my people, which were not my people; and her beloved, which was not beloved.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Paul takes Hosea's word and says it of the ones he was sent to. Those who were not a people are the scattered house, called again by name in the place they were driven to. So the all nations of the commission is the place of that calling, and the ones called are the house.$n$,8,$n$The Pauline-citation of Hosheia 1:10.$n$,$n$Romans 9:25 — *I will call them my people, which were not my people.* Hosea's word of calling those who were not a people is spoken of the scattered house, which tells who the sending is for.$n$),
(3175,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','acts',2,5,$n$The substantial-Pentecost-substance — *out of every nation under heaven* + the substantial-scattered-Yahudim-substance.$n$,$n$Acts 2:5 — *And there were dwelling at Jerusalem Yahudim (Jews), devout men, out of every nation under heaven.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Here the nations are a place people came from. The ones standing in Jerusalem are Yahudim (Jews), scattered and drawn back for the feast, and each hears the word in the language of the land he lives in. Every nation under heaven is where the scattered seed was found, and the sending after the rising goes to them there.$n$,8,$n$The substantial-Pentecost-substance — *out of every nation under heaven* + the substantial-scattered-Yahudim-substance.$n$,$n$Acts 2:5 — *Yahudim (Jews), devout men, out of every nation under heaven.* Yahudim (Jews) from every nation under heaven show the all nations of the commission to be the lands the scattered were found in.$n$),
(3176,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','acts',11,19,$n$The substantial-substance-of-the-Gospel-going-to-the-Yahudim-substance-only first.$n$,$n$Acts 11:19 — *Now they which were scattered abroad upon the persecution that arose about Stephen travelled as far as Phenice, and Cyprus, and Antioch, preaching the word to none but unto the Yahudim (Jews) only.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Those scattered after Stephen carried the word as far as Phenice, Cyprus and Antioch, and gave it to the Yahudim (Jews) only. The sheep stayed the sheep, even when the road ran through the nations. The commission to all nations is a road, and who stood at the end of the road did not change.$n$,8,$n$The substantial-substance-of-the-Gospel-going-to-the-Yahudim-substance-only first.$n$,$n$Acts 11:19 — *preaching the word to none but unto the Yahudim (Jews) only.* The scattered carry the word through Phenice, Cyprus and Antioch to the Yahudim (Jews) only, so the road through the nations was still for the house.$n$),
(3177,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','matthew',24,14,$n$The substantial-gospel-of-the-kingdom-preached-for-a-witness-unto-all-nations.$n$,$n$Matthew 24:14 — *And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) The power given to him is what carries this word everywhere. It goes out to the nations as a witness, and when the sheep in them have heard it, the end comes. The nations are where the word is heard, and the sheep are the ones who hear.$n$,8,$n$The substantial-gospel-of-the-kingdom-preached-for-a-witness-unto-all-nations.$n$,$n$Matthew 24:14 — *shall be preached in all the world for a witness unto all nations.* The gospel of the kingdom goes to every nation as a witness, and the end waits on the sheep in them hearing it.$n$),
(3179,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','james',1,1,$n$*The twelve tribes which are scattered abroad.*$n$,$n$James 1:1 — *James, a servant of Elohim (God) and of the Lord Yahusha HaMashiach (Lord Jesus Christ), to the twelve tribes which are scattered abroad, greeting.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) James writes to a people, the twelve tribes, and he finds them scattered abroad. The commission to every nation is the same sending, and this letter lands on the same people in the same lands. A servant of Yahusha (Jesus) is writing to the sheep, not to a new nation.$n$,8,$n$*The twelve tribes which are scattered abroad.*$n$,$n$James 1:1 — *to the twelve tribes which are scattered abroad.* James addresses the twelve tribes scattered abroad, the same sheep in the same lands the sending goes to.$n$),
(3181,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','2-samuel',7,23,$n$The substantial-substance the Father walked-out the substantial-redemption-of-Yashar'el.$n$,$n$2 Samuel 7:23 — *And what one nation in the earth is like thy people, even like Yashar'el (Israel), whom Elohim (God) went to redeem for a people to himself, and to make him a name, and to do for you great things and terrible, for thy land, before thy people, which thou redeemedst to thee from Egypt, from the nations and their gods?* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Elohim (God) went to redeem Yashar'el (Israel) out of Egypt, from the nations and their gods. Bringing a people out from among the nations is old work. So when all power is given and the sending goes to all nations, it goes to bring the redeemed people out from among them, not to turn the nations into that people.$n$,8,$n$The substantial-substance the Father walked-out the substantial-redemption-of-Yashar'el.$n$,$n$2 Samuel 7:23 — *whom Elohim (God) went to redeem for a people to himself.* Elohim (God) redeemed Yashar'el (Israel) out from the nations, which is how the sending to the nations now is to be read.$n$),
(3182,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','daniel',7,13,$n$*Dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him* per Red Line #12.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) The one who says all power is given is the one Daniel saw brought near to the Ancient of days. What he receives there is dominion, glory and a kingdom, and the nations are named as those who serve it. Daniel keeps the word *like*, one like the Son of Adam, and the giving is the Father's. Nothing in it turns the nations into the people.$n$,8,$n$*Dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him.*$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven.* Daniel sees one like the Son of Adam brought before the Ancient of days, the giving behind the power Yahusha (Jesus) names.$n$),
(3183,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','micah',4,1,$n$The nations flow-unto-the-mountain-of-Yahuah's-house.$n$,$n$Micah 4:1 — *But in the last days it shall come to pass, that the mountain of the house of Yahuah (LORD) shall be established in the top of the mountains, and it shall be exalted above the hills; and people shall flow unto it.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) Micah sees a later hour. The nations come up themselves to the mountain of Yahuah (LORD), to be taught his ways and to walk his paths, and the law goes out from Zion. That is a different day from the sending. In the commission he goes out after the sheep where they are. In the last days the nations flow to the mountain.$n$,8,$n$The nations flow-unto-the-mountain-of-Yahuah's-house.$n$,$n$Micah 4:1 — *the mountain of the house of Yahuah (LORD) shall be established in the top of the mountains.* In the last days the nations flow to the mountain of Yahuah (LORD) to be taught, a later hour than the sending after the sheep.$n$),
(3184,'canon','matthew',28,18,$n$And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.$n$,'canon','isaiah',56,1,$n$The substantial-Tanakh-substance the sons-of-the-stranger-joined-to-Yahuah-substance — the scattered-coming-home-substance.$n$,$n$Isaiah 56:1 — *Thus saith Yahuah (LORD), Keep ye judgment, and do justice: for my salvation is near to come, and my righteousness to be revealed.* *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18) The Torah was spoken long before the sending. Yahuah (LORD) says to keep judgment and do justice, because his salvation is near, and the next verse blesses the one who keeps the sabbath. The teaching of all he commanded is that same keeping. Nothing in the power given is power to put the law down.$n$,8,$n$The substantial-Tanakh-substance the sons-of-the-stranger-joined-to-Yahuah-substance — the scattered-coming-home-substance.$n$,$n$Isaiah 56:1 — *Keep ye judgment, and do justice.* Yahuah (LORD) calls for keeping judgment and doing justice, and the teaching to observe all things is that same keeping of Torah.$n$),
(7021,'canon','luke',9,1,$n$Then he called his twelve disciples together, and gave them power and authority over all devils, and to cure diseases.$n$,'canon','matthew',10,5,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | The Twelve sent out at Luke 9 — the same commissioning architecture as Matthew 10, working out the gathering of the scattered seed first through Yashar'eli (Israelite) territory.$n$,$n$Matthew 10:5 — *These twelve Yahusha (Jesus) sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:* *Then he called his twelve disciples together, and gave them power and authority over all devils, and to cure diseases.* (Luke 9:1) Luke gives the twelve power and authority over devils and disease, and Matthew tells where they were to take it. Not *into the way of the Gentiles*, and not into a Samaritan city, but to the lost sheep. The power is for the sheep, and the fence tells whose they are.$n$,8,$n$The Twelve sent out at Luke 9 — the same commissioning architecture as Matthew 10, working out the gathering of the scattered seed first through Yashar'eli (Israelite) territory.$n$,$n$Matthew 10:5 — *Go not into the way of the Gentiles.* The twelve are sent with power, and the word to them fences the road toward the lost sheep of the house.$n$),
(5272,'canon','mark',13,10,$n$And the gospel must first be published among all nations.$n$,'canon','isaiah',49,6,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *I will also give thee for a light to the Gentiles* (Yeshayahu/Isaiah 49:6).$n$,$n$Isaiah 49:6 — *And he said, It is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Yashar'el (Israel): I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth.* *And the gospel must first be published among all nations.* (Mark 13:10) The servant's own work is named first: raise up the tribes of Jacob and restore the preserved of Yashar'el (Israel). The light to the nations is given beside it. So the gospel published among all nations is the servant's work carried into the lands where the tribes were scattered.$n$,8,$n$*I will also give thee for a light to the Gentiles* (Yeshayahu/Isaiah 49:6).$n$,$n$Isaiah 49:6 — *to raise up the tribes of Jacob, and to restore the preserved of Yashar'el (Israel).* The servant's own errand is to raise up the tribes and restore the preserved of Yashar'el (Israel), and the light to the nations is the reach of that errand.$n$),
(7051,'canon','luke',13,29,$n$And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God).$n$,'canon','matthew',8,11,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God)* (Luke 13:29) — the four-winds gathering language. NOT the inherited Gentile-inclusion gospel; the prophetic-gathering of the scattered seed of Yashar'el (Israel) from the territories of dispersion. Yeshayahu (Isaiah) 43:5-6 substance.$n$,$n$Matthew 8:11 — *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* *And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God).* (Luke 13:29) Luke has them coming from the four quarters, and Matthew says whose table it is, the table of Abraham, Isaac and Jacob. The many come to the fathers from every direction, which is how the prophets speak of the scattered coming home. The centurion standing there heard and believed, seed revealed by hearing.$n$,8,$n$*And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God)* (Luke 13:29) — the four-winds gathering language. NOT the inherited Gentile-inclusion gospel; the prophetic-gathering of the scattered seed of Yashar'el (Israel) from the territories of dispersion. Yeshayahu (Isaiah) 43:5-6 substance.$n$,$n$Matthew 8:11 — *many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob.* The many come from east and west to sit with Abraham, Isaac and Jacob, the scattered seed gathered to the fathers' table.$n$),
(5271,'canon','mark',13,10,$n$And the gospel must first be published among all nations.$n$,'canon','hosea',1,10,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *Ye are the sons of the living Elohim* (Hoshea/Hosea 1:10) — the scattered seed addressed.$n$,$n$Hosea 1:10 — *Yet the number of the children of Yashar'el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God).* *And the gospel must first be published among all nations.* (Mark 13:10) Hosea says the calling happens in the very place the people were told they were not his. Among all nations is that place. The gospel is published there because that is where the sons of the living Elohim (God) are waiting to be called sons again.$n$,8,$n$*Ye are the sons of the living Elohim* (Hoshea/Hosea 1:10) — the scattered seed addressed.$n$,$n$Hosea 1:10 — *in the place where it was said unto them, Ye are not my people.* The word of sonship is said in the place the people were told they were not his, which is the nations.$n$),
(7125,'canon','luke',24,47,$n$And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem.$n$,'canon','matthew',28,19,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | The *among all nations, beginning at Yerushalayim (Jerusalem)* (v.47) is panta-ta-ethnē-as-SCOPE-of-proclamation language — the same gathering-of-the-scattered-from-every-nation substance the Matt 28 commission carries. The *beginning at Yerushalayim* is the gathering-out-of-Yahudah-first register; the *all nations* is the territories-of-the-scattered, not the categorical-Gentile-inclusion.$n$,$n$Matthew 28:19 — *Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* *And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem.* (Luke 24:47) Luke has the word going out among all nations, beginning at Jerusalem, and Matthew has the sending that carries it. The going is toward the places the scattered were driven. What is taught there is told in the next line: to observe all he commanded. That is Torah kept, carried to the lost sheep wherever they are.$n$,8,$n$The *among all nations, beginning at Yerushalayim (Jerusalem)* (v.47) is panta-ta-ethnē-as-SCOPE-of-proclamation language — the same gathering-of-the-scattered-from-every-nation substance the Matt 28 commission carries. The *beginning at Yerushalayim* is the gathering-out-of-Yahudah-first register; the *all nations* is the territories-of-the-scattered, not the categorical-Gentile-inclusion.$n$,$n$Matthew 28:19 — *Go ye therefore, and teach all nations.* The sending goes to every nation, where the scattered are, and the teaching it carries is the keeping of all he commanded.$n$),
(5269,'canon','mark',13,10,$n$And the gospel must first be published among all nations.$n$,'canon','matthew',24,14,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *The gospel must first be published among all nations.* *Panta ta ethnē* as the territory-of-the-scattered-seed, not the categorical-three-categories audience.$n$,$n$Matthew 24:14 — *And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.* *And the gospel must first be published among all nations.* (Mark 13:10) Mark has the gospel going out to every nation first, and Matthew says what it is and what follows. It is the gospel of the kingdom, it goes out *for a witness*, and after that the end. The nations are where it is published. The word is for the sheep scattered in them, and when they have heard, the end comes.$n$,8,$n$*The gospel must first be published among all nations.* *Panta ta ethnē* as the territory-of-the-scattered-seed, not the categorical-three-categories audience.$n$,$n$Matthew 24:14 — *this gospel of the kingdom shall be preached in all the world.* The gospel of the kingdom is published to all nations for a witness, and the end follows once it has been heard.$n$),
(5270,'canon','mark',13,10,$n$And the gospel must first be published among all nations.$n$,'canon','matthew',28,19,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | Matthew 28:19's Great Commission — same scope.$n$,$n$Matthew 28:19 — *Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* *And the gospel must first be published among all nations.* (Mark 13:10) Mark's *all nations* is the same all nations Matthew gives the eleven. It is the territory, the lands where the scattered seed was driven, and not a new kind of people to be turned into the people. What is taught there is told in the next line: observe all things he commanded.$n$,8,$n$Matthew 28:19's Great Commission — same scope.$n$,$n$Matthew 28:19 — *teach all nations, baptizing them in the name of the Father.* Go and teach all nations is the same sending as the gospel published among all nations, aimed at the places the sheep are scattered.$n$),
(5377,'canon','mark',16,15,$n$And he said unto them, Go you into all the world, and preach the gospel to every creature.$n$,'canon','isaiah',49,6,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *I will also give thee for a light to the Gentiles* (Yeshayahu/Isaiah 49:6).$n$,$n$Isaiah 49:6 — *And he said, It is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Yashar'el (Israel): I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth.* *And he said unto them, Go you into all the world, and preach the gospel to every creature.* (Mark 16:15) Go into all the world, and Isaiah says what the world is for: the tribes of Jacob raised up, the preserved of Yashar'el (Israel) brought back, and a light given to the nations. The reach is the whole earth because the scattered are all over it.$n$,8,$n$*I will also give thee for a light to the Gentiles* (Yeshayahu/Isaiah 49:6).$n$,$n$Isaiah 49:6 — *that thou mayest be my salvation unto the end of the earth.* The salvation reaches the end of the earth because the tribes to be restored are scattered that far.$n$),
(5376,'canon','mark',16,15,$n$And he said unto them, Go you into all the world, and preach the gospel to every creature.$n$,'canon','hosea',1,10,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *Ye are the sons of the living Elohim (God)* (Hoshea/Hosea 1:10).$n$,$n$Hosea 1:10 — *Yet the number of the children of Yashar'el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God).* *And he said unto them, Go you into all the world, and preach the gospel to every creature.* (Mark 16:15) Go into all the world, and Hosea says what is waiting there. The children of Yashar'el (Israel) are as the sand of the sea, and a word is spoken to them in the very place they were cast off. The preaching goes out after sons, and the whole world is simply where they lie.$n$,8,$n$*Ye are the sons of the living Elohim (God)* (Hoshea/Hosea 1:10).$n$,$n$Hosea 1:10 — *Ye are the sons of the living Elohim (God).* The scattered are told they are sons in the place they were told otherwise, so the whole world is the field they lie in.$n$),
(5375,'canon','mark',16,15,$n$And he said unto them, Go you into all the world, and preach the gospel to every creature.$n$,'canon','matthew',28,18,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *Go ye into all the world, and preach the gospel to every creature.* The all-the-world scope is the territory-of-the-scattered-seed.$n$,$n$Matthew 28:18 — *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* *And he said unto them, Go you into all the world, and preach the gospel to every creature.* (Mark 16:15) Go into all the world only makes sense from the one who says this. The power is given him, and the sending rides on it. It is given by the Father, as Daniel saw. What goes out under it is the one errand to the lost sheep, now sought wherever they were driven.$n$,8,$n$*Go ye into all the world, and preach the gospel to every creature.* The all-the-world scope is the territory-of-the-scattered-seed.$n$,$n$Matthew 28:18 — *All power is given unto me in heaven and in earth.* The power given to him in heaven and earth is what stands behind the going into all the world.$n$),
(5378,'canon','mark',16,15,$n$And he said unto them, Go you into all the world, and preach the gospel to every creature.$n$,'canon','john',10,27,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *My sheep hear my voice* (Yochanan/John 10:27).$n$,$n$John 10:27 — *My sheep hear my voice, and I know them, and they follow me:* *And he said unto them, Go you into all the world, and preach the gospel to every creature.* (Mark 16:15) Go into all the world and preach, and the ones who hear are the sheep. He does not say the hearing makes them sheep. He says they hear because they are his, and he knows them. The word goes out to every creature, and the sheep in the world know the voice when it reaches them.$n$,8,$n$*My sheep hear my voice* (Yochanan/John 10:27).$n$,$n$John 10:27 — *My sheep hear my voice, and I know them.* The sheep hear his voice and follow, so the preaching in all the world finds the sheep who are already his.$n$),
(5392,'canon','mark',16,20,$n$And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.$n$,'canon','acts',14,3,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | *The disciples going forth, the Lord working with them.* The Markan ending names the apostolic walk that Acts opens into (Acts 14:3). (NT-Lord rule: titular for ascended Yahusha — *Lord* preserved per S182 §7.)$n$,$n$Acts 14:3 — *Long time therefore abode they speaking boldly in Yahuah (Lord), which gave testimony unto the word of his grace, and granted signs and wonders to be done by their hands.* *And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.* (Mark 16:20) Mark ends with the sent ones going out and Yahusha (Jesus) working with them. Acts shows it in Iconium. They speak boldly, and Yahuah (Lord) gives testimony to the word with signs and wonders by their hands. The sending is carried out in the cities where the scattered live, beginning in their synagogues.$n$,8,$n$*The disciples going forth, the Lord working with them.* The Markan ending names the apostolic walk that Acts opens into (Acts 14:3). (NT-Lord rule: titular for ascended Yahusha — *Lord* preserved per S182 §7.)$n$,$n$Acts 14:3 — *gave testimony unto the word of his grace, and granted signs and wonders.* Yahuah (Lord) gives testimony to the word with signs and wonders by their hands, as Mark's ending says Yahusha (Jesus) worked with them.$n$),
(5393,'canon','mark',16,20,$n$And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.$n$,'canon','acts',19,11,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | Acts 19:11-12's signs-and-wonders confirming the apostolic word.$n$,$n$Acts 19:11 — *And Elohim (God) wrought special miracles by the hands of Paul:* *And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.* (Mark 16:20) The signs following are not the sent ones' own. Elohim (God) wrought them, by the hands of Paul. So the confirming Mark names is Elohim (God) at work through those who carry the word out to the scattered.$n$,8,$n$Acts 19:11-12's signs-and-wonders confirming the apostolic word.$n$,$n$Acts 19:11 — *Elohim (God) wrought special miracles by the hands of Paul.* Elohim (God) works the miracles by the hands of Paul, the confirming Mark's ending says followed those who went out.$n$),
(5394,'canon','mark',16,20,$n$And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.$n$,'canon','hebrews',2,3,$n$thread:great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance | Hebrews 2:3-4's *Elohim (God) also bearing them witness, both with signs and wonders*.$n$,$n$Hebrews 2:3 — *How shall we escape, if we neglect so great salvation; which at the first began to be spoken by Yahusha (Lord), and was confirmed unto us by them that heard him;* *And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.* (Mark 16:20) Hebrews says the word began to be spoken by Yahusha (Jesus) himself and was confirmed by those who heard him. That is Mark's ending in a sentence: they went out, he worked with them, and the word was confirmed. The next verse adds that Elohim (God) bore them witness with signs and wonders.$n$,8,$n$Hebrews 2:3-4's *Elohim (God) also bearing them witness, both with signs and wonders*.$n$,$n$Hebrews 2:3 — *began to be spoken by Yahusha (Lord), and was confirmed unto us by them that heard him.* The word began with Yahusha (Jesus) and was confirmed by those who heard him, which is the going out Mark's ending describes.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (8, 'great-commission-all-nations-as-territories-of-the-scattered-seed-not-categorical-three-categories-substance', $n$Go ye therefore, and teach all nations — all power given him, and the sheep sought where they were scattered (Matthew 10 and 15; Hosea 1; Isaiah 11; James 1)$n$, $n$Go ye therefore, and teach all nations — all power given him, and the sheep sought where they were scattered (Matthew 10 and 15; Hosea 1; Isaiah 11; James 1)$n$, $n$It ain't new. The risen one sends the eleven with a word about power and a word about nations:

*And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18)

*Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* (Matthew 28:19)

*All power is given unto me*: given, by the Father, and Daniel had already seen the giving:

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

Then *all nations*. Before his death the sending had a fence on it, and he told the twelve who they were sent to:

*These twelve Yahusha (Jesus) sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:* (Matthew 10:5)

*But go rather to the lost sheep of the house of Yashar'el (Israel).* (Matthew 10:6)

*But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24)

The sheep did not change after the rising; the fence came down, because the sheep were out past it. The prophets had said where the lost sheep of the house were: in the nations, under another name, waiting to be called sons again:

*Yet the number of the children of Yashar'el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God).* (Hosea 1:10)

*And it shall come to pass in that day, that Yahuah (Lord) shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.* (Isaiah 11:11)

*And he shall set up an ensign for the nations, and shall assemble the outcasts of Yashar'el (Israel), and gather together the dispersed of Yahudah (Judah) from the four corners of the earth.* (Isaiah 11:12)

*And say unto them, Thus saith Adonai Yahuah (the Lord GOD); Behold, I will take the children of Yashar'el (Israel) from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land:* (Ezekiel 37:21)

Paul quotes Hosea's verse for the ones he was sent to:

*And it shall come to pass, that in the place where it was said unto them, Ye are not my people; there shall they be called the children of the living Elohim (God).* (Romans 9:26)

And the letters are addressed to the same people in the same places. James writes to the tribes, Peter to the scattered:

*James, a servant of Elohim (God) and of the Lord Yahusha HaMashiach (Lord Jesus Christ), to the twelve tribes which are scattered abroad, greeting.* (James 1:1)

*Peter, an apostle of Yahusha HaMashiach (Jesus Christ), to the strangers scattered throughout Pontus, Galatia, Cappadocia, Asia, and Bithynia,* (1 Peter 1:1)

*All nations* is where the sheep are, not who the sheep are. The errand is the one errand, the lost sheep of the house of Yashar'el (Israel), now sought in every place they were driven to, because the death that frees the divorced house has been died. The nations themselves come up to the mountain in the reign, to be taught, and that is a different hour and a different verse:

*And many nations shall come, and say, Come, and let us go up to the mountain of Yahuah (LORD), and to the house of the Elohim (God) of Jacob; and he will teach us of his ways, and we will walk in his paths: for the law shall go forth of Zion, and the word of Yahuah (LORD) from Jerusalem.* (Micah 4:2)

The gospel of the kingdom goes to all nations for a witness, and the end comes when the sheep in them have heard:

*And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.* (Matthew 24:14)$n$, $n$It ain't new. The risen one sends the eleven with a word about power and a word about nations:

*And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth.* (Matthew 28:18)

*Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit):* (Matthew 28:19)

*All power is given unto me*: given, by the Father, and Daniel had already seen the giving:

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

Then *all nations*. Before his death the sending had a fence on it, and he told the twelve who they were sent to:

*These twelve Yahusha (Jesus) sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:* (Matthew 10:5)

*But go rather to the lost sheep of the house of Yashar'el (Israel).* (Matthew 10:6)

*But he answered and said, I am not sent but unto the lost sheep of the house of Yashar'el (Israel).* (Matthew 15:24)

The sheep did not change after the rising; the fence came down, because the sheep were out past it. The prophets had said where the lost sheep of the house were: in the nations, under another name, waiting to be called sons again:

*Yet the number of the children of Yashar'el (Israel) shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living Elohim (God).* (Hosea 1:10)

*And it shall come to pass in that day, that Yahuah (Lord) shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.* (Isaiah 11:11)

*And he shall set up an ensign for the nations, and shall assemble the outcasts of Yashar'el (Israel), and gather together the dispersed of Yahudah (Judah) from the four corners of the earth.* (Isaiah 11:12)

*And say unto them, Thus saith Adonai Yahuah (the Lord GOD); Behold, I will take the children of Yashar'el (Israel) from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land:* (Ezekiel 37:21)

Paul quotes Hosea's verse for the ones he was sent to:

*And it shall come to pass, that in the place where it was said unto them, Ye are not my people; there shall they be called the children of the living Elohim (God).* (Romans 9:26)

And the letters are addressed to the same people in the same places. James writes to the tribes, Peter to the scattered:

*James, a servant of Elohim (God) and of the Lord Yahusha HaMashiach (Lord Jesus Christ), to the twelve tribes which are scattered abroad, greeting.* (James 1:1)

*Peter, an apostle of Yahusha HaMashiach (Jesus Christ), to the strangers scattered throughout Pontus, Galatia, Cappadocia, Asia, and Bithynia,* (1 Peter 1:1)

*All nations* is where the sheep are, not who the sheep are. The errand is the one errand, the lost sheep of the house of Yashar'el (Israel), now sought in every place they were driven to, because the death that frees the divorced house has been died. The nations themselves come up to the mountain in the reign, to be taught, and that is a different hour and a different verse:

*And many nations shall come, and say, Come, and let us go up to the mountain of Yahuah (LORD), and to the house of the Elohim (God) of Jacob; and he will teach us of his ways, and we will walk in his paths: for the law shall go forth of Zion, and the word of Yahuah (LORD) from Jerusalem.* (Micah 4:2)

The gospel of the kingdom goes to all nations for a witness, and the end comes when the sheep in them have heard:

*And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.* (Matthew 24:14)$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 8 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 8 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (great-commission-all-nations) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — great-commission-all-nations done.'
